import sys,json,hashlib,html
from pathlib import Path
from bs4 import BeautifulSoup

def sha(b): return hashlib.sha256(b).hexdigest()
def esc(t): return html.escape(str(t),quote=True)
def build(source, model):
    assert sha(source)==model['baseline']['librarySha256'], 'Unexpected F3 input'
    assert model['studentAuthorized'] is False and model['authority']['state']=='PROVISIONAL_COMPLETE'
    cases=model['model']['cases']; assert len(cases)==3 and len({c['id'] for c in cases})==3
    for c in cases:
        assert c['input']==c['useful']+c['thermal'] and c['useful']==model['model']['useful'] and c['efficiency']*c['input']==100*c['useful']
    s=BeautifulSoup(source,'html.parser'); resources=model['resources']; nodes=model['concepts']; ids={n['id'] for n in nodes}; assert len(ids)==len(nodes)
    for n in nodes: assert set(n['relations'])<=ids
    def insert(parent,markup):
        frag=BeautifulSoup(markup,'html.parser'); parent.append(frag)
    def fragment(markup): return BeautifulSoup(markup,'html.parser')
    def link(route,label,cls='energy-link'): return f'<a class="{cls}" href="#{esc(route)}">{esc(label)} →</a>'
    def back(): return '<a class="back" href="#universo-energia">← Universo Energia</a>'
    def related(*items): return '<nav class="energy-related" aria-label="Collegamenti tematici">'+''.join(link(*item) for item in items)+'</nav>'
    def title(id,kicker,name,desc): return f'<header class="sectionhead"><span class="kicker">{esc(kicker)}</span><h1 id="heading-{id}" tabindex="-1">{esc(name)}</h1><p>{esc(desc)}</p></header>'
    def view(id,body): return f'<section class="view energy-view" hidden id="{id}" aria-labelledby="heading-{id}">{body}</section>'
    cards=''.join(f'<a class="energy-card" href="#{esc(r["route"])}"><span class="energy-step">{i+1:02d} · {esc(r["action"])}</span><h2>{esc(r["title"])}</h2><p>{esc(r["description"])}</p><small>{esc(r["type"])} · {esc(r["duration"])}</small><span class="energy-arrow" aria-hidden="true">→</span></a>' for i,r in enumerate(resources[:4]))
    home=s.select_one('#home .hero'); insert(home,'<p class="energy-home-entry">'+link('universo-energia','Esplora il tema Energia','energy-entry')+'</p>')
    insert(s.select_one('#home'),'<section class="energy-spotlight" aria-labelledby="energy-home-title"><span class="kicker">Universi della conoscenza</span><h2 id="energy-home-title">Energia: una storia, molte scoperte</h2><p>Racconto, spiegazione, laboratorio virtuale e mappa. Scegli da dove iniziare.</p>'+link('universo-energia','Entra nell’universo Energia')+'</section>')
    for id in ('storie','laboratori','scoperte'):
        insert(s.find(id=id),related(('universo-energia','Tutte le esperienze sull’energia')))
    insert(s.select_one('#libro .reader-page'),related(('universo-energia','Universo Energia'),('energia','Comprendi: la spiegazione'),('laboratorio-energia','Sperimenta: il confronto virtuale'),('mappa-energia','Esplora: la mappa')))
    insert(s.find(id='energia'),related(('universo-energia','Universo Energia'),('laboratorio-energia','Sperimenta il confronto'),('libro','Leggi il racconto')))
    insert(s.find(id='scheda-energia'),related(('universo-energia','Universo Energia'),('laboratorio-energia','Apri il laboratorio virtuale')))
    main=s.select_one('main.wrap')
    insert(main,view('universo-energia','<a class="back" href="#home">← Biblioteca</a>'+title('universo-energia','Atlas · Universo tematico',model['title'],model['question'])+'<p class="energy-meta">'+esc(model['audience'])+' · Percorso libero, durate indicative</p><div class="energy-grid">'+cards+'</div><aside class="energy-extra"><h2>Porta le idee su carta</h2><p>'+esc(resources[4]['description'])+'</p>'+link('scheda-energia','Apri la scheda operativa')+'</aside><p class="source-note">Candidato in revisione docente. Le quattro azioni sono indipendenti e non richiedono un ordine obbligatorio.</p>'))
    opts=''.join(f'<option value="{c["id"]}"'+(' selected' if c['id']=='B' else '')+f'>Lampada {c["id"]} — {c["efficiency"]}% quota utile</option>' for c in cases)
    rows=''.join(f'<tr><th scope="row">{c["id"]}</th><td>{c["input"]}</td><td>{c["useful"]}</td><td>{c["thermal"]}</td><td>{c["efficiency"]}%</td></tr>' for c in cases)
    lab=back()+title('laboratorio-energia','Sperimenta · Simulazione','La stessa luce, meno energia?','Confronta la lampada A del racconto con un secondo modello. Il risultato utile rimane fisso a 20 J.')+f'''<p class="energy-assumptions">{esc(model['model']['assumptions'])}</p><div class="energy-controls"><label for="energy-choice">Confronta la lampada A con</label><select id="energy-choice">{opts}</select><button type="button" id="energy-reset">Ripristina B</button></div><div class="energy-bars" aria-hidden="true"><div><strong>A · 100 J</strong><div class="energy-scale"><span class="energy-useful" style="width:20%"></span><span class="energy-thermal" style="width:80%"></span></div></div><div><strong id="energy-bar-label">B · 50 J</strong><div class="energy-scale"><span class="energy-useful" style="width:20%"></span><span id="energy-thermal-bar" class="energy-thermal" style="width:30%"></span></div></div><p class="energy-legend"><span>■ Luce utile</span> <span>■ Trasferimento termico</span> · scala comune 0–100 J</p></div><div class="energy-comparison" aria-live="polite" aria-atomic="true" id="energy-result"></div><details class="energy-details"><summary>Tutti i dati del modello</summary><div class="energy-table-scroll" tabindex="0" role="region" aria-label="Tabella dei dati"><table><caption>Modelli di lampada: energia in joule, quota utile in percentuale</caption><thead><tr><th scope="col">Mod.</th><th scope="col">Entrata</th><th scope="col">Luce</th><th scope="col">Calore</th><th scope="col">Utile %</th></tr></thead><tbody>{rows}</tbody></table></div><p>{esc(model['model']['extension'])}</p></details><aside class="energy-extra"><h2>Ragiona sui risultati</h2><p>Quale soluzione richiede meno energia per fornire lo stesso effetto utile? Motiva la scelta usando i bilanci. Perché i dati non permettono di stabilire la causa dell’affievolimento della piazza?</p><p>Annota la spiegazione su carta. Non è richiesto alcun esperimento elettrico.</p></aside>'''+related(('scheda-energia','Scheda operativa'),('energia','Spiegazione'),('mappa-energia','Mappa delle conoscenze'))
    insert(main,view('laboratorio-energia',lab))
    nodebuttons=''.join(f'<button class="map-node" type="button" data-concept="{esc(n["id"])}" aria-pressed="{"true" if i==0 else "false"}" aria-controls="map-panel"><span>{esc(n["title"])}</span><small>{esc(n["scope"])}</small></button>' for i,n in enumerate(nodes))
    # All content is present in the page as an accessible textual alternative; JS only selects a panel.
    panels=''.join(f'<article class="map-concept" data-panel="{esc(n["id"])}"'+(' hidden' if i else '')+f'><h2>{esc(n["title"])}</h2><p>{esc(n["text"])}</p><h3>Collegamenti</h3><div class="map-relations">'+''.join(f'<button type="button" data-concept="{esc(rel)}" aria-controls="map-panel">{esc(next(x["title"] for x in nodes if x["id"]==rel))} →</button>' for rel in n['relations'])+'</div>'+link(n['link'],n['linkLabel'])+'</article>' for i,n in enumerate(nodes))
    alltext=''.join(f'<li><strong>{esc(n["title"])}</strong> — {esc(n["text"])} Collegato a: '+', '.join(esc(next(x['title'] for x in nodes if x['id']==rel)) for rel in n['relations'])+'.</li>' for n in nodes)
    maphtml=back()+title('mappa-energia','Esplora · Atlante','Atlante dell’energia','Scegli un concetto, scopri le sue relazioni e passa direttamente alle opere collegate. I collegamenti introduttivi non costituiscono obiettivi già valutati.')+'<div class="map-layout"><div class="map-nodes" role="group" aria-label="Concetti energetici">'+nodebuttons+'</div><div id="map-panel" class="map-panel" aria-live="polite">'+panels+'</div></div><details class="energy-details"><summary>Mappa completa in forma testuale</summary><ul>'+alltext+'</ul></details>'+related(('universo-energia','Universo Energia'),('laboratorio-energia','Laboratorio virtuale'))
    insert(main,view('mappa-energia',maphtml))
    css='''
.energy-home-entry{margin-top:9px!important}.energy-entry{display:inline-flex;align-items:center;min-height:44px;color:#f6dfad;font-weight:750;text-decoration:underline;text-underline-offset:4px}.energy-spotlight,.energy-extra{background:#fff;border:1px solid #cbdadf;border-radius:12px;padding:clamp(14px,3vw,24px);margin:20px 0}.energy-spotlight h2,.energy-extra h2{font:600 clamp(1.4rem,3vw,2rem) Georgia,serif;margin:5px 0 8px}.energy-link{display:inline-flex;align-items:center;min-height:44px;padding:8px 12px;border:1px solid #a9bdc5;border-radius:8px;background:#fff;color:#174e69;font-weight:650;text-decoration:underline;text-underline-offset:3px;max-width:100%}.energy-meta{font-size:.88rem;color:#51627a}.energy-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.energy-card{position:relative;display:flex;flex-direction:column;gap:6px;min-width:0;padding:20px 24px 18px 16px;border:1px solid #cbdadf;border-radius:13px;background:white;box-shadow:0 6px 15px #12213b0b;border-top:5px solid #2a6e7b}.energy-card:nth-child(2){border-top-color:#99652e}.energy-card:nth-child(3){border-top-color:#53688f}.energy-card:nth-child(4){border-top-color:#427d72}.energy-card h2{font:600 clamp(1.35rem,3vw,2rem)/1.15 Georgia,serif;margin:4px 0}.energy-card p{margin:0;color:#344c60}.energy-card small{margin-top:auto;color:#51627a}.energy-step{font-size:.8rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:#22586a}.energy-arrow{position:absolute;right:9px;bottom:12px;color:#22586a}.energy-related{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.energy-view{min-width:0;max-width:1100px;margin:auto}.energy-assumptions{background:#e8eef1;border-left:4px solid #527988;padding:12px 16px;border-radius:5px}.energy-controls{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:16px 0}.energy-controls label{font-weight:700}.energy-controls select,.energy-controls button,.map-node,.map-relations button{font:inherit;color:#174e69;min-height:44px;background:white;border:1px solid #a9bdc5;border-radius:8px;padding:8px 12px;max-width:100%;cursor:pointer}.energy-controls select{min-width:0}.energy-controls :focus-visible,.map-node:focus-visible,.map-relations button:focus-visible,.energy-details summary:focus-visible{outline:3px solid #168097;outline-offset:3px}.energy-bars{display:grid;gap:12px;background:white;border:1px solid #cbdadf;border-radius:12px;padding:16px}.energy-scale{display:flex;height:28px;border-radius:4px;overflow:hidden;background:#e8edf0;margin-top:5px}.energy-useful{background:#26745f}.energy-thermal{background:#a96520}.energy-legend{font-size:.86rem;margin:0}.energy-legend span:first-child{color:#1c604e}.energy-legend span:nth-child(2){color:#8c5418}.energy-comparison{margin:14px 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.energy-comparison>div{background:white;border:1px solid #cbdadf;border-radius:10px;padding:14px;min-width:0}.energy-comparison strong{display:block;font-size:1.15rem}.energy-comparison p{margin:5px 0}.energy-comparison .comparison-conclusion{grid-column:1/-1;background:#e5f0ed}.energy-details{border:1px solid #cbdadf;border-radius:10px;background:white;margin:16px 0;padding:10px 14px}.energy-details summary{font-weight:700;min-height:44px;cursor:pointer;padding:8px 0}.energy-table-scroll{overflow-x:auto;max-width:100%}.energy-table-scroll table{border-collapse:collapse;width:100%;min-width:360px}.energy-table-scroll th,.energy-table-scroll td{padding:9px;border:1px solid #cbdadf;text-align:left;white-space:nowrap}.energy-table-scroll caption{text-align:left;font-weight:650;margin:8px 0}.map-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:16px;align-items:start}.map-nodes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.map-node{display:flex;flex-direction:column;align-items:flex-start;text-align:left;min-width:0;gap:4px}.map-node span{font-weight:750}.map-node small{font-size:.77rem;color:#51627a}.map-node[aria-pressed=true]{background:#154a58;color:white;border-color:#154a58}.map-node[aria-pressed=true] small{color:#e2eef1}.map-panel{background:white;border:1px solid #cbdadf;border-radius:12px;padding:18px;min-width:0}.map-panel h2{font:600 1.6rem Georgia,serif;margin:0 0 8px}.map-panel h3{font-size:1rem}.map-relations{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}.energy-details li{margin:10px 0}.energy-view [hidden]{display:none!important}@media(max-width:650px){.energy-grid,.map-layout,.energy-comparison{grid-template-columns:minmax(0,1fr)}.energy-card{padding:14px 20px 14px 14px}.energy-home-entry{margin-top:4px!important}.map-nodes{gap:6px}.map-panel{padding:14px}.energy-controls{align-items:stretch;flex-direction:column}.energy-spotlight,.energy-extra{margin:14px 0}}@media(min-width:390px) and (max-width:650px){.energy-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.energy-card{padding:12px 14px 12px 10px;gap:4px}.energy-card h2{font-size:1.18rem}.energy-card p{font-size:.86rem}.energy-card small{font-size:.73rem}.energy-card .energy-arrow{display:none}}@media print{.energy-related,.energy-controls,.energy-entry,.map-nodes,.map-relations{display:none!important}}
'''
    s.style.string=str(s.style.string)+css
    script=str(s.script.string)
    # Theme entry can be reached from story, material and map; existing router resolves all view IDs.
    js='''
const energyCases=CASES;
const energyChoice=document.getElementById('energy-choice');
function energyUpdate(){const a=energyCases[0],b=energyCases.find(c=>c.id===energyChoice.value);if(!b)return;document.getElementById('energy-bar-label').textContent=b.id+' · '+b.input+' J';document.getElementById('energy-thermal-bar').style.width=b.thermal+'%';const result=document.getElementById('energy-result');result.replaceChildren();for(const c of [a,b]){const card=document.createElement('div');const title=document.createElement('strong');title.textContent='Lampada '+c.id+' · '+c.efficiency+'%';const p=document.createElement('p');p.textContent=c.input+' J = '+c.useful+' J di luce utile + '+c.thermal+' J di calore';card.append(title,p);result.append(card);}const conclusion=document.createElement('div');conclusion.className='comparison-conclusion';const p=document.createElement('p');p.textContent=b.id===a.id?'Stesso modello: nessuna differenza di energia richiesta.':'A parità di 20 J utili, '+b.id+' richiede '+(a.input-b.input)+' J in meno rispetto ad A. È un confronto simulato, non una diagnosi.';conclusion.append(p);result.append(conclusion);}
energyChoice.addEventListener('change',energyUpdate);document.getElementById('energy-reset').addEventListener('click',()=>{energyChoice.value='B';energyUpdate();energyChoice.focus();});energyUpdate();
function conceptSelect(id){for(const b of document.querySelectorAll('.map-node'))b.setAttribute('aria-pressed',String(b.dataset.concept===id));for(const p of document.querySelectorAll('.map-concept'))p.hidden=p.dataset.panel!==id;}
for(const b of document.querySelectorAll('[data-concept]'))b.addEventListener('click',()=>{conceptSelect(b.dataset.concept);if(b.closest('.map-relations'))document.querySelector('.map-node[data-concept="'+b.dataset.concept+'"]').focus();});
'''.replace('CASES',json.dumps(cases,ensure_ascii=False,separators=(',',':')))
    s.script.string=script+js
    out=str(s)
    # No image or external-network additions; the public catalog is not modified.
    return out
if __name__=='__main__':
    src,model,out=map(Path,sys.argv[1:]); result=build(src.read_bytes(),json.loads(model.read_text()));out.write_text(result,encoding='utf-8');print(sha(out.read_bytes()))
